const http = require('http');
const { createProxyServer } = require('http-proxy');

const proxy = createProxyServer({ changeOrigin: true });

http.createServer((req, res) => {
  req.url = req.url.replace(/^{{strip_prefix}}/, '');
  proxy.web(req, res, { target: '{{target_url}}' }, (err) => {
    res.writeHead(502); res.end(`proxy error: ${err.message}`);
  });
}).listen({{listen_port}}, () => console.log('proxy on {{listen_port}} -> {{target_url}}'));
